EXPECTED = {"GH-142", "GH-149", "DOC-ATLAS-403"}

def units_A(ds): return list(ds)
def units_B(ds):
    out = []
    for d in ds:
        if d.source_type == "github":
            head, _, tail = d.content.partition("\n\n")
            pieces = [head, tail] if tail.strip() else [d.content]
        elif d.source_type == "document":
            blocks = [b.strip() for b in d.content.split("\n\n") if b.strip()]
            heading = blocks[0] if blocks and blocks[0].startswith("#") else ""
            body, merged = (blocks[1:] if heading else blocks), []
            for b in body:
